CREATE SCHEMA IF NOT EXISTS recruiting_ops;
CREATE TABLE IF NOT EXISTS recruiting_ops.consents (candidate_id TEXT NOT NULL, consent_version TEXT NOT NULL, scopes TEXT[] NOT NULL, granted_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, PRIMARY KEY(candidate_id,consent_version));
CREATE TABLE IF NOT EXISTS recruiting_ops.applications (application_id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL, job_id TEXT NOT NULL, revision INTEGER NOT NULL, redacted_features JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(candidate_id,job_id,revision));
CREATE TABLE IF NOT EXISTS recruiting_ops.match_decisions (decision_id BIGSERIAL PRIMARY KEY, application_id TEXT NOT NULL UNIQUE REFERENCES recruiting_ops.applications(application_id), score NUMERIC(5,2), evidence JSONB NOT NULL, policy_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('blocked','recruiter_review','shortlisted')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recruiting_ops.interview_transitions (transition_id BIGSERIAL PRIMARY KEY, application_id TEXT NOT NULL REFERENCES recruiting_ops.applications(application_id), from_state TEXT NOT NULL, to_state TEXT NOT NULL, actor_id TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_consent_expiry ON recruiting_ops.consents(expires_at) WHERE revoked_at IS NULL;
